function validate([position, m]) {
  if (!Array.isArray(position) || position.length < 2 || position.length > 100000) return 'position needs 2 to 10^5 values.';
  if (position.some(v => !Number.isInteger(v) || v < 1 || v > 1000000000)) return 'Each position is an integer from 1 to 10^9.';
  if (new Set(position).size !== position.length) return 'All positions must be different.';
  if (!Number.isInteger(m) || m < 2 || m > position.length) return 'm is between 2 and position.length.';
  return null;
}

