function maxDistance(position, m) {
  position.sort((a, b) => a - b);
  const n = position.length;

  function canPlace(gap) {
    let placed = 1;
    let last = position[0];
    for (let i = 1; i < n; i++) {
      if (position[i] - last >= gap) {
        placed++;
        last = position[i];
      }
    }
    return placed >= m;
  }

  let low = 1;
  let high = Math.floor((position[n - 1] - position[0]) / (m - 1));
  while (low < high) {
    const mid = Math.floor((low + high + 1) / 2);
    if (canPlace(mid)) {
      low = mid;
    } else {
      high = mid - 1;
    }
  }
  return low;
}

