function maxDistance(position, m) {
  const sorted = [...position].sort((a, b) => a - b);
  const n = sorted.length;
  // best[k][i]: largest smallest force with k + 1 balls, the right-most one in basket i.
  let best = sorted.map(() => Infinity);
  for (let k = 1; k < m; k++) {
    const next = sorted.map(() => -Infinity);
    for (let i = 0; i < n; i++)
      for (let j = 0; j < i; j++) next[i] = Math.max(next[i], Math.min(best[j], sorted[i] - sorted[j]));
    best = next;
  }
  return Math.max(...best);
}

