function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 1500 + Math.floor(rand() * 501) : 2 + Math.floor(rand() * 7);
  const limit = large || rand() < 0.2 ? 1000000000 : 5 + Math.floor(rand() * 40);
  const span = Math.max(limit, n);
  const seen = new Set();
  while (seen.size < n) seen.add(1 + Math.floor(rand() * span));
  const position = [...seen];
  const m = rand() < 0.15 ? n : 2 + Math.floor(rand() * (n - 1));
  return [position, m];
}
